[
f(n)-2n\sim c\frac{n}{\log n}
]

let (f(N)) be the largest size of a set
[
A\subseteq {1,2,\ldots,N}
]
such that there do not exist three distinct elements (a,b,c\in A) satisfying
[
[a,b]=[b,c]=[a,c].
]

