[
U_n=(n,2n)\cap\mathbb N
={n+1,n+2,\ldots,2n-1}
]

determine whether
[
f(n)\le n^{1/2+o(1)}
\qquad\text{as }n\to\infty.
]

* proving only a bound of the form
  [
  f(n)\le n^{1/2+\delta}
